#include <stdio.h>
int main(void) {
    char tag[8] = "";
    double amount = 0.0;
    if (scanf("%7s", tag) != 1) return 1;
    if (scanf("%lf", &amount) != 1) return 1;
    printf("tag=%s amount=%.2f\n", tag, amount);
    return 0;
}

#include <stdio.h>
int main(void) {
    char nickname[12] = "";
    if (scanf("%11s", nickname) != 1) return 1;
    printf("Hello, %s!\n", nickname);
    return 0;
}

#include <stdio.h>
#include <string.h>
int main(void) {
    char call_sign[12] = "Pine";
    unsigned int used = strlen(call_sign);
    printf("text=%s length=%u capacity=%u\n",
           call_sign, used, sizeof(call_sign));
    return 0;
}

#include <stdio.h>
#define RADIUS 2
int main(void) {
    const double pi = 3.141592653589793;
    double area = pi * RADIUS * RADIUS;
    printf("area=%.2f\n", area);
    return 0;
}

#include <stdio.h>
#include <limits.h>
#include <float.h>
int main(void) {
    printf("int_limit=%d float_digits=%d double_digits=%d\n",
           INT_MAX, FLT_DIG, DBL_DIG);
    return 0;
}

#include <stdio.h>
int main(void) {
    char letter = 'Z';
    int count = 5;
    unsigned int id = 26u;
    double price = 0.5;
    printf("letter=%c count=%d id=%u price=%.1f text=%s\n",
           letter, count, id, price, "oak");
    return 0;
}

#include <stdio.h>
int main(void) {
    double value = 3.5;
    printf("|%8.2f| %.2e %g\n", value, value, value);
    return 0;
}

#include <stdio.h>
int main(void) {
    double value = 2.5;
    printf("|%+7.2f| |%07.2f| |%-7.2f|\n",
           value, value, value);
    return 0;
}

#include <stdio.h>
int main(void) {
    const char *label = "terminal";
    printf("|%10.4s| |%-10.4s|\n", label, label);
    return 0;
}

#include <stdio.h>
int main(void) {
    int pieces = 1200;
    long shipment = 70000L;
    printf("pieces=%d shipment=%ld\n", pieces, shipment);
    /* Passing shipment to %d would violate the required argument type. */
    return 0;
}

#include <stdio.h>
int main(void) {
    double ordinary = 0.125;
    long double extended = 0.125L;
    printf("double=%.3f extended=%.3Lf\n", ordinary, extended);
    return 0;
}

#include <stdio.h>
int main(void) {
    int written = printf("ready\n");
    if (written < 0) return 1;
    printf("characters=%d\n", written);
    return 0;
}

#include <stdio.h>
int main(void) {
    printf("A message can be written "
           "on two source lines.\n");
    return 0;
}

#include <stdio.h>
int main(void) {
    int key = 0;
    double value = 0.0;
    char word[8] = "";
    if (scanf("%d %lf %7s", &key, &value, word) != 3) return 1;
    printf("key=%d value=%.1f word=%s\n", key, value, word);
    return 0;
}

#include <stdio.h>
int main(void) {
    int width = 9;
    int precision = 3;
    double value = 1.25;
    printf("|%*.*f|\n", width, precision, value);
    return 0;
}

#include <stdio.h>
int main(void) {
    int kept = 0;
    if (scanf("%*s%d", &kept) != 1) return 1;
    printf("kept=%d\n", kept);
    return 0;
}

