#include <stdio.h>
#include <string.h>
int main(void) {
    char line[64] = "";
    if (fgets(line, 64, stdin) == NULL) {
        line[0] = 0;
    }
    unsigned int length = strlen(line);
    printf("%u\n", length);
    return 0;
}

