#include <stdio.h>
#include <string.h>
int main(void) {
    char incoming[64] = "";
    char copied[64] = "";
    if (fgets(incoming, 64, stdin) == NULL) {
        incoming[0] = 0;
    }
    strcpy(copied, incoming);
    printf("%s\n", copied);
    return 0;
}

