#include <stdio.h>
#include <string.h>
int main(void) {
    char message[64] = "";
    if (fgets(message, 64, stdin) == NULL) {
        printf("%u\n", strlen(message));
    } else {
        unsigned int measured = strlen(message);
        printf("%u\n", measured);
    }
    return 0;
}
